+// Helper function to convert a slice of alternating key-value pairs into a map
+func mapResults(pairs []string) map[string]string {
+	resultMap := make(map[string]string)
+	for i := 0; i < len(pairs); i += 2 {
+		resultMap[pairs[i]] = pairs[i+1]
+	}
+	return resultMap
+}
