+// Helper function to convert a slice of interface{} to a slice of strings
+func convertToStringSlice(interfaces []interface{}) []string {
+	strings := make([]string, len(interfaces))
+	for i, v := range interfaces {
+		strings[i] = v.(string)
+	}
+	return strings
