+func evalAPPEND(args []string, store *dstore.Store) []byte {
+    if len(args) != 2 {
+        return diceerrors.NewErrArity("APPEND")
+    }
+
+    key, value := args[0], args[1]
+
+    obj := store.Get(key)
+    var newValue string
+
+    if obj == nil {
+        // Key does not exist; create new string key with the value
+        newValue = value
+    } else {
+        // Key exists; ensure it is of string type
+        errWithMessage := object.AssertType(obj.TypeEncoding, object.ObjTypeString)
+        if errWithMessage != nil {
+            return errWithMessage
+        }
+
+        // Retrieve current value as string
+        var currentValueStr string
+        switch obj.TypeEncoding.Encoding {
+        case object.ObjEncodingInt:
+            currentValueStr = strconv.FormatInt(obj.Value.(int64), 10)
+        case object.ObjEncodingEmbStr, object.ObjEncodingRaw:
+            currentValueStr = obj.Value.(string)
+        default:
+            return diceerrors.NewErrWithFormattedMessage("ERR unsupported encoding: %d", obj.TypeEncoding.Encoding)
+        }
+
+        // Append the new value
+        newValue = currentValueStr + value
+    }
+
+    // Store the new value
+    newObj := store.NewObj(newValue, -1, object.ObjTypeString, object.ObjEncodingRaw)
+    store.Put(key, newObj)
+
+    return clientio.Encode(len(newValue), false)
+}", "landed_diff": "--- a/internal/eval/eval.go
